267.sql:
SELECT `bond_type`
FROM bond
WHERE `molecule_id` BETWEEN 'TR000' AND 'TR050';

291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE label = '+';

387.sql:
WITH c_cols AS (
    SELECT c.`setCode`, c.`name`, c.`colorIdentity`, c.`colors`, c.`type`, c.`subtypes`, c.`supertypes`, c.`rarity`, c.`layout`, c.`frameVersion`, c.`faceName`, c.`faceConvertedManaCost`, c.`manaCost`, c.`convertedManaCost`, c.`power`, c.`toughness`, c.`text`, c.`flavorText`, c.`originalText`, c.`keywords`, c.`printings`, c.`number`, c.`uuid`, c.`id`
    FROM cards AS c
    WHERE c.`setCode` = 'OGW'
)
SELECT `name`, `colorIdentity` FROM c_cols;

419.sql:
SELECT COUNT(*) AS answer
FROM cards
WHERE `borderColor` = 'borderless' AND `edhrecRank` > 12000;

591.sql:
SELECT COUNT(DISTINCT b.UserId) AS answer
FROM badges AS b
WHERE b.Name = 'Supporter' AND strftime('%Y', b.Date) = '2011';

617.sql:
SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:37:33.0';

625.sql:
SELECT COUNT(*) AS answer
FROM users
WHERE Location LIKE '%New York%';

882.sql:
SELECT MIN(year) AS first_year
FROM races
WHERE name = 'Singapore Grand Prix';

1035.sql:
SELECT DISTINCT `team_fifa_api_id`
FROM Team_Attributes
WHERE `buildUpPlaySpeed` > 50 AND `buildUpPlaySpeed` < 60;

1393.sql:
SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';
